  "claim_memory_current_heads",
  "claim_usage_stats",
  "claim_mural_cues",
  "claim_derivations",
  "claim_operation_receipts",
  "claim_operation_effects",
  "claim_outbox_consumer_checkpoints",
  "claim_outbox_prune_state"
