      provider: "openai-compatible",
      model: data.model?.trim() ?? "",
      endpoint: data.endpoint?.trim() ?? "",
      ...apiKey ? { api_key: apiKey } : {},
      ...inputType ? { input_type: inputType } : {},
      ...queryInputType ? { query_input_type: queryInputType } : {},
